<?php require_once __DIR__.'/../app/bootstrap.php';ensure_feedback_schema();if(setting('feedback_public_enabled','0')!=='1'){http_response_code(404);exit('La comunidad de feedback no está habilitada.');}$q=db()->query("SELECT ft.*,u.username,p.display_name,p.avatar,(SELECT COUNT(*) FROM feedback_messages fm WHERE fm.thread_id=ft.id) message_count FROM feedback_threads ft JOIN users u ON u.id=ft.seller_id LEFT JOIN profiles p ON p.user_id=u.id WHERE ft.is_public=1 ORDER BY ft.updated_at DESC,ft.created_at DESC");$items=$q->fetchAll();require __DIR__.'/../partials/header.php';?>
<link rel="stylesheet" href="<?=url('assets/css/feedback.css')?>"><section class="feedback-hero public"><div><span class="eyebrow">🌐 Comunidad de mejora</span><h1>Ideas de nuestros vendedores</h1><p>Comentarios que la administración decidió compartir para construir la plataforma junto a su comunidad.</p></div></section><section class="public-feedback-grid"><?php if(!$items):?><article class="empty-public"><h2>Aún no hay feedback público</h2><p>Las ideas aparecerán aquí cuando sean autorizadas por la administración.</p></article><?php endif;?><?php foreach($items as $it):?><article class="public-feedback-card"><header><img src="<?=url($it['avatar']?:'assets/img-avatar.svg')?>"><div><b><?=e($it['display_name']?:$it['username'])?></b><span><?=feedback_category_label($it['category'])?></span></div><span class="feedback-status <?=$it['status']?>"><?=feedback_status_label($it['status'])?></span></header><h2><?=e($it['subject'])?></h2><div class="feedback-card-stars"><small>Experiencia con la administración</small><?=feedback_stars((int)($it['seller_rating']??0))?></div><footer><span>💬 <?=$it['message_count']?> mensajes</span><span>📅 <?=date('d/m/Y',strtotime($it['created_at']))?></span></footer></article><?php endforeach;?></section><?php require __DIR__.'/../partials/footer.php';?>
